mapper.select:
SELECT c.id as companyId, c.company_name as companyName, c.short_name as shortName, c.logo as logo, c.address as address, c.nature as nature, c.people_size as peopleSize, c.industry as industry, c.financ_stage as financStage, c.review_status as reviewStatus, c.commit_date as commitDate, u.real_name as commitUser FROM company c LEFT JOIN users u ON u.id = c.commit_user_id WHERE 1 = 1
and c.company_name LIKE CONCAT('%', #{paramMap.companyName}, '%')
and u.real_name LIKE CONCAT('%', #{paramMap.realName}, '%')
and c.review_status = #{paramMap.reviewStatus}
and c.commit_date >= #{paramMap.commitDateStart}
and c.commit_date <= #{paramMap.commitDateEnd}
ORDER BY c.commit_date DESC
